const $=s=>document.querySelector(s);
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=k=>({'<Esc>':'Esc','<Enter>':'↵',' ':'Space','<BS>':'⌫','<C-r>':'Ctrl+r'}[k]||k);
const keyHTML=k=>`<kbd>${escapeHTML(label(k))}</kbd>`;
let saved={};try{saved=JSON.parse(localStorage.getItem('vim-fieldwork-v1')||'{}')}catch{}
let done=new Set(Array.isArray(saved.done)?saved.done:[]), index=Number.isInteger(saved.index)?Math.max(0,Math.min(missions.length-1,saved.index)):0, expanded=missions[index].ch, keys=[],submitted=false, demoTimer=null;
function persist(){try{localStorage.setItem('vim-fieldwork-v1',JSON.stringify({done:[...done],index}))}catch{}}
const cm=CodeMirror($('#editor'),{value:'',keyMap:'vim',lineNumbers:true,tabSize:2,indentUnit:2,showCursorWhenSelecting:true,viewportMargin:Infinity,ariaLabel:'Your mission text. Vim key bindings enabled. Press Tab to leave the editor in Normal mode.'});
cm.setOption('extraKeys',{'Tab':function(c){if(!c.state.vim.insertMode){$('#hint').focus()}else c.replaceSelection('  ')}});
function renderNav(){
 $('#progress-count').textContent=`${done.size}/${missions.length}`;$('#progress-bar').style.width=`${done.size/missions.length*100}%`;
 $('#course').innerHTML=chapters.map((c,ch)=>`<div class="chapter"><button class="chapter-toggle" data-ch="${ch}" aria-expanded="${expanded===ch}"><span class="num">0${ch+1}</span>${c}<span class="chevron">${expanded===ch?'−':'+'}</span></button>${expanded===ch?missions.map((m,i)=>m.ch===ch?`<button class="lesson ${index===i?'active':''}" data-mission="${i}" ${index===i?'aria-current="step"':''}><span class="lesson-dot">${done.has(i)?'✓':index===i?'●':'○'}</span>${escapeHTML(m.title)}</button>`:'').join(''):''}</div>`).join('');
 document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>{expanded=expanded===+b.dataset.ch?-1:+b.dataset.ch;renderNav()});
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>load(+b.dataset.mission));
}
function showTarget(m){let a=0,b=0;while(a<m.before.length&&a<m.after.length&&m.before[a]===m.after[a])a++;while(b<m.before.length-a&&b<m.after.length-a&&m.before.at(-1-b)===m.after.at(-1-b))b++;
 let offset=0;$('#target').innerHTML=m.after.split('\n').map((line,i)=>{let content=[...line].map((c,j)=>{const pos=offset+j;return pos>=a&&pos<m.after.length-b?`<span class="change">${c===' '?'·':escapeHTML(c)}</span>`:escapeHTML(c)}).join('');if(m.after.length-b===a&&offset<=a&&a<=offset+line.length){const local=a-offset;content='<span class="change">'+escapeHTML(line)+'</span>'}offset+=line.length+1;return `<div class="target-line"><span class="line-no">${i+1}</span><span>${content||' '}</span></div>`}).join('');
}
function load(i){$('aside').classList.remove('path-open');$('#course-toggle').setAttribute('aria-expanded','false');index=i;expanded=missions[i].ch;const m=missions[i];CodeMirror.Vim.handleKey(cm,'<Esc>');cm.setValue(m.before);cm.setCursor(...m.cursor);cm.clearHistory();keys=[];submitted=false;$('#feedback').innerHTML='';$('#hint-box').hidden=true;$('#title').textContent=m.title;$('#instruction').textContent=m.instruction;$('#concept').textContent=m.concept;$('#chapter-label').textContent=`0${m.ch+1} / ${chapters[m.ch].toUpperCase()}`;$('#mission-number').textContent=`MISSION ${String(i+1).padStart(2,'0')} OF ${missions.length}`;showTarget(m);renderNav();renderKeys();persist();updateCursor();$('#mode').textContent='NORMAL';$('#submit').textContent='Check my edit ↗';requestAnimationFrame(()=>{cm.refresh();cm.focus()})}
function renderKeys(){$('#keys').innerHTML=keys.length?keys.slice(-70).map(keyHTML).join(''):'<span class="placeholder">Your keystrokes will appear here…</span>';$('#key-count').textContent=`${keys.length} ${keys.length===1?'key':'keys'}`;$('#keys').scrollTop=$('#keys').scrollHeight}
function updateCursor(){const p=cm.getCursor();$('#cursor').textContent=`${p.line+1}:${p.ch+1}`}
cm.on('cursorActivity',updateCursor);cm.on('vim-mode-change',e=>{$('#mode').textContent=e.mode.toUpperCase()});
cm.getWrapperElement().addEventListener('keydown',e=>{if(['Shift','Control','Alt','Meta','CapsLock'].includes(e.key)||e.metaKey||(e.key==='Tab'&&!cm.state.vim.insertMode))return;keys.push(e.key==='Escape'?'<Esc>':e.key==='Enter'?'<Enter>':e.key==='Backspace'?'<BS>':e.ctrlKey?`<C-${e.key}>`:e.key);renderKeys()},true);
cm.on('change',()=>{if(submitted){submitted=false;$('#feedback').innerHTML='';$('#submit').textContent='Check my edit ↗'}});
$('#reset').onclick=()=>{load(index);cm.focus()};
$('#hint').onclick=()=>{$('#hint-box').hidden=!$('#hint-box').hidden;$('#hint-box').textContent=missions[index].hint};
$('#submit').onclick=()=>{
 const m=missions[index],value=cm.getValue();if(value!==m.after){const actual=value.split('\n'),expected=m.after.split('\n');let line=0;while(line<Math.max(actual.length,expected.length)&&actual[line]===expected[line])line++;$('#feedback').innerHTML=`<div class="feedback error"><h2>Not quite — you’re still in it.</h2><p>Check line ${line+1}. Your edit needs to match the target exactly, including spaces and line breaks.</p><button class="quiet" id="keep-editing">Keep editing</button></div>`;$('#keep-editing').onclick=()=>cm.focus();return}
 submitted=true;done.add(index);persist();renderNav();const efficient=keys.length>0&&keys.length<=m.keys.length;
 $('#feedback').innerHTML=`<div class="feedback"><div class="success-label">✓ MISSION COMPLETE</div><h2>${efficient?'Nicely done. A small edit, well made.':'That’s the edit. Now make it feel effortless.'}</h2><p>${keys.length} ${keys.length===1?'key':'keys'} in your attempt · ${m.keys.length} in the suggested route. ${efficient?'Your route is just as compact or shorter.':'Here’s an idiomatic route worth trying.'}</p><div class="solution">${m.keys.map(keyHTML).join('')}</div><p>${escapeHTML(m.why)}</p><div class="feedback-actions"><button id="watch" class="quiet">▷ Watch the edit</button><button id="next" class="primary">${index===missions.length-1?'Finish course ✓':'Next mission →'}</button></div></div>`;
 $('#watch').onclick=()=>demo(m);$('#next').onclick=()=>{if(index<missions.length-1){load(index+1);cm.focus()}else{$('#modal-title').textContent=done.size===missions.length?'A little Vim. A lot of progress.':'Keep your practice going.';$('#modal-body').innerHTML=`<p>You’ve completed ${done.size} of ${missions.length} missions. Revisit any mission to try a shorter route.</p><p class="modal-note">Practice is saved in this browser. The course uses a browser Vim keymap; terminal commands, plugins, and file operations are outside this sandbox.</p>`;$('#modal').showModal()}};
};
function feed(editor,sequence,step){let command=null;for(const key of sequence){if(command!==null){if(key==='<Enter>'){if(command[0]===':')CodeMirror.Vim.handleEx(editor,command.slice(1));else{CodeMirror.Vim.handleKey(editor,'/');const inp=editor.getWrapperElement().querySelector('.CodeMirror-dialog input');inp.value=command.slice(1);inp.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,which:13,bubbles:true}));}command=null}else command+=key;continue}if((key===':'||key==='/')&&sequence[0]===key&&!editor.state.vim.insertMode){command=key;continue}if(editor.state.vim.insertMode&&!key.startsWith('<')){editor.replaceSelection(key);CodeMirror.signal(editor,'inputRead',editor,{text:[key],origin:'+input'})}else CodeMirror.Vim.handleKey(editor,key);if(step)step(key)}}
function demo(m){clearTimeout(demoTimer);$('#modal-title').textContent='One edit, step by step.';$('#modal-body').innerHTML='<div id="demo"></div><div class="demo-keys">'+m.keys.map(keyHTML).join('')+'</div><p class="modal-note">'+escapeHTML(m.why)+'</p><button class="quiet" id="again">Replay ↺</button>';$('#modal').showModal();const d=CodeMirror($('#demo'),{value:m.before,keyMap:'vim',lineNumbers:true,readOnly:false,tabSize:2});d.setCursor(...m.cursor);let n=0;function tick(){if(!$('#modal').open)return;n++;d.setValue(m.before);CodeMirror.Vim.handleKey(d,'<Esc>');d.setCursor(...m.cursor);feed(d,m.keys.slice(0,n));document.querySelectorAll('.demo-keys kbd').forEach((k,i)=>k.classList.toggle('played',i<n));if(n<m.keys.length)demoTimer=setTimeout(tick,360)}demoTimer=setTimeout(tick,450);$('#again').onclick=()=>{clearTimeout(demoTimer);n=0;tick()};setTimeout(()=>d.refresh(),0)}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>clearTimeout(demoTimer));$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
$('#reference').onclick=()=>{$('#modal-title').textContent='Your pocket reference';$('#modal-body').innerHTML=`<p class="modal-note">Normal mode is home. Press Escape to get back. Combine an operator with a motion or a text object: <kbd>c</kbd> + <kbd>iw</kbd> = change this word.</p><div class="ref-grid">${[
['Move','h j k l — left, down, up, right','w / b / e — next word / back / word end','0 / ^ / $ — line start / content start / end','gg / G — first / last line','f{char} / t{char} — find / stop before'],
['Edit','i / a — insert before / after','I / A — insert at start / end','o / O — new line below / above','x / r{char} — delete / replace character','u / Ctrl+r — undo / redo'],
['Compose','d / c / y — delete / change / yank','iw / aw — inner word / around word','i" / i( / i[ — inside delimiters','dd / cc / yy — operate on whole line','p / P — put after / before'],
['Go further','v / V — visual / visual line mode','/text then Enter — search; n repeats','* — next occurrence of current word','. — repeat the last change','qa … q / @a — record / play macro']].map(r=>`<section><h3>${r[0]}</h3>${r.slice(1).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</section>`).join('')}</div><p class="modal-note">Click the editor to capture keys. Tab in Normal mode moves focus to the buttons. A physical keyboard works best. This is a browser Vim sandbox powered by CodeMirror, with original exercises.</p>`;$('#modal').showModal()};
load(index);
window.runCourseTests=()=>{const node=document.createElement('div');document.body.append(node);const test=CodeMirror(node,{keyMap:'vim'});const results=missions.map(m=>{CodeMirror.Vim.handleKey(test,'<Esc>');test.setValue(m.before);test.setCursor(...m.cursor);try{feed(test,m.keys);return {title:m.title,pass:test.getValue()===m.after,actual:test.getValue(),expected:m.after}}catch(e){return {title:m.title,pass:false,error:String(e)}}});node.remove();return results};
if(location.search.includes('selftest')){const results=runCourseTests();const pre=document.createElement('pre');pre.id='test-results';pre.textContent=JSON.stringify(results,null,2);document.body.prepend(pre)}

$("#course-toggle").onclick=()=>{const open=$("aside").classList.toggle("path-open");$("#course-toggle").setAttribute("aria-expanded",String(open))};
